# ── Rebuild node mapping (identical to tri_city_experiment.py) ────────────────
PROCESSED_STATIONS_DF = "data/processed/stations_data.csv"
WEST_COAST_MIN_LAT, WEST_COAST_MAX_LAT = 32, 39
WEST_COAST_MIN_LNG, WEST_COAST_MAX_LNG = -120, -110

max_independent_set = [
    (32.178328, -110.960207), (32.596725, -117.019495), (32.794671, -115.539473),
    (33.30006,  -111.96835),  (33.39639,  -110.76888),  (33.603063, -114.598023),
    (33.899899, -118.207088), (34.02094,  -117.385415), (34.118101, -116.45646),
    (34.421443, -119.684178), (34.689589, -118.130371), (34.886448, -117.079423),
    (35.01643,  -110.675005), (35.263617, -112.194139), (35.400164, -119.399727),
    (36.075856, -119.043996), (36.220567, -115.125553), (36.72136,  -119.761165),
    (37.161682, -113.434692), (37.72495,  -113.056978), (38.164391, -112.278183),
    (38.786621, -112.084147),
]

stations_df = pd.read_csv(PROCESSED_STATIONS_DF)
stations_df['snap_to'] = stations_df['snap_to'].apply(ast.literal_eval)
stations_west = stations_df[
    (stations_df['lat'] >= WEST_COAST_MIN_LAT) & (stations_df['lat'] <= WEST_COAST_MAX_LAT) &
    (stations_df['lng'] >= WEST_COAST_MIN_LNG) & (stations_df['lng'] <= WEST_COAST_MAX_LNG)
]
station_coords = set(zip(stations_west['lat'], stations_west['lng']))
all_selected_nodes = list(set(list(station_coords) + list(max_independent_set)))

def node_pos(idx):
    lat, lng = all_selected_nodes[idx]
    return lng, lat  # cartopy wants (lon, lat)

